// Creative Engineering; moved from kubejs/startup_scripts/items/coil_blocks.js on 2026-11-04 (creative_split.md 7.13, wave 8), rows unchanged.
// Wire coil blocks (creativeengineering:coil_<metal>) - the pack's own tier fillers
// alongside IE's coil_lv / coil_mv (copper / electrum). Steel has its own block here now
// (was aliased to IE's coil_hv); electrum still uses IE's coil_mv.
//
// Blockstate, block model and block-item model are generated by KubeJS from the .texture()
// calls below (cube: top texture on up/down, side texture on the four sides, textures at
// creativeengineering:block/coil_block/coil_<metal>_{side,top}.png). KubeJS's generated pack outranks mod jars, so hand-authored JSONs in this jar would be ignored;
// do not add them back (2026-11-07: they rendered untextured after the jar move).

const COIL_BLOCK_METALS = [
    'aluminum', 'brass', 'constantan', 'gold', 'iron',
    'lead', 'nickel', 'silver', 'zinc', 'steel'
];

StartupEvents.registry('block', e => {
    COIL_BLOCK_METALS.forEach(metal => {
        const name = metal.charAt(0).toUpperCase() + metal.slice(1);
        const top = 'creativeengineering:block/coil_block/coil_' + metal + '_top';
        const side = 'creativeengineering:block/coil_block/coil_' + metal + '_side';
        e.create('creativeengineering:coil_' + metal)
            .displayName(name + ' Coil Block')
            .material('metal')
            .soundType('metal')
            .hardness(3.0)
            .resistance(6.0)
            .requiresTool(true)
            .texture('up', top).texture('down', top)
            .texture('north', side).texture('south', side)
            .texture('east', side).texture('west', side)
            .texture('particle', side)
            .tagBlock('minecraft:mineable/pickaxe')
            .tagBlock('minecraft:needs_iron_tool');
    });
});
